ernment", "duty_rate": "25%"}}, {"claim_id": "claim_27bf23e8b60858eb157e55e2", "quote": "President Donald Trump said Monday that he was increasing tariffs on imported autos, pharmaceuticals, and lumber from South Korea from 15% to 25%", "url": "https://www.cnbc.com/2026/01/26/trump-south-korea-tariffs-trade-autos-pharma.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "increasing tariffs on imported autos, pharmaceuticals, and lumber from South Korea from 15% to 25%", "duty_rate": "25%", "announcement_date": "Monday", "reported_policy_status": "increasing"}}]}, {"pair_id": "conflict_42b595b2abe78a1221f6b004", "claim_ids": ["claim_078c6d0714f84622198c455c", "claim_dc22af36e2e08f3e99d677af"], "query_ids": ["q_61"], "claims": [{"claim_id": "claim_078c6d0714f84622198c455c", "quote": "In January 2026, President Trump criticized the ROK government's speed at implementing its investment commitments and stated his intentions to raise tariffs on South Korean exports to 25%. The higher tariff rate had not been implemented as of early March 2026.", "url": "https://www.congress.gov/crs-product/IF10733", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "ROK government", "duty_rate": "25%"}}, {"claim_id": "claim_dc22af36e2e08f3e99d677af", "quote": "President Trump on Monday said he is raising tariffs on South Korea because the nation has not yet approved a trade deal with the U.S. that the two countries agreed to last year.", "url": "https://www.cbsnews.com/news/trump-south-korea-tariffs-25", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "raising tariffs on South Korea", "duty_rate": "25%", "announcement_date": "January 26, 2026", "reported_policy_status": "announcing the stepped-up duties"}}]}, {"pair_id": "conflict_25c6a8bebb87d51158575161", "claim_ids": ["claim_198c7e274be6aafdca56d6f6", "claim_2