te": "25%", "effective_date": "2025"}}, {"claim_id": "claim_27bf23e8b60858eb157e55e2", "quote": "President Donald Trump said Monday that he was increasing tariffs on imported autos, pharmaceuticals, and lumber from South Korea from 15% to 25%", "url": "https://www.cnbc.com/2026/01/26/trump-south-korea-tariffs-trade-autos-pharma.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "increasing tariffs on imported autos, pharmaceuticals, and lumber from South Korea from 15% to 25%", "duty_rate": "25%", "announcement_date": "Monday", "reported_policy_status": "increasing"}}]}, {"pair_id": "conflict_781e3315b76a17fb81567a2f", "claim_ids": ["claim_213b1866d6331f331e8f6c9c", "claim_27bf23e8b60858eb157e55e2"], "query_ids": ["q_61"], "claims": [{"claim_id": "claim_213b1866d6331f331e8f6c9c", "quote": "Additionally, the November 2025 agreement lowered from 25% to 15% the country-specific \"reciprocal\" tariff that President Trump imposed in April 2025 on most South Korean goods under Executive Order (E.O.) 14257.", "url": "https://www.congress.gov/crs-product/IF10733", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Executive Order (E.O.) 14257", "legal_authority": "Executive Order (E.O.) 14257", "affected_product": "most South Korean goods", "duty_rate": "25%", "effective_date": "April 2025"}}, {"claim_id": "claim_27bf23e8b60858eb157e55e2", "quote": "President Donald Trump said Monday that he was increasing tariffs on imported autos, pharmaceuticals, and lumber from South Korea from 15% to 25%", "url": "https://www.cnbc.com/2026/01/26/trump-south-korea-tariffs-trade-autos-pharma.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "increasing tariffs on imported autos, pharmaceuticals, and lumber from South Korea from 15% to 25%", "duty_rate": "25%", "announcement_date": "Monday", "reported_