biles and parts", "duty_rate": "15%", "effective_date": "approximately by September 17"}}, {"claim_id": "claim_72c5f35f3ec01a4cbc0a8b65", "quote": "the United States imposed a 15% tariff on most imports from Japan, a reduction from the 25% that President Trump initially proposed but an increase from 2024 U.S. tariff rates.", "url": "https://www.congress.gov/crs-product/IN12608", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "United States", "duty_rate": "15%", "announcement_date": "July 2025", "effective_date": "2025", "reported_policy_status": "imposed"}}]}, {"pair_id": "conflict_8cb407b1fc252312acc6776e", "claim_ids": ["claim_4be697aefc6a551e2955fc97", "claim_72c5f35f3ec01a4cbc0a8b65"], "query_ids": ["q_62"], "claims": [{"claim_id": "claim_4be697aefc6a551e2955fc97", "quote": "In 2025, Trump imposed 25% tariffs on vehicles and auto parts", "url": "https://www.congress.gov/crs-product/IN12608", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Trump", "tariff_program": "Section 232 of the Trade Expansion Act of 1962", "duty_rate": "25%", "effective_date": "2025", "reported_policy_status": "imposed"}}, {"claim_id": "claim_72c5f35f3ec01a4cbc0a8b65", "quote": "the United States imposed a 15% tariff on most imports from Japan, a reduction from the 25% that President Trump initially proposed but an increase from 2024 U.S. tariff rates.", "url": "https://www.congress.gov/crs-product/IN12608", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "United States", "duty_rate": "15%", "announcement_date": "July 2025", "effective_date": "2025", "reported_policy_status": "imposed"}}]}, {"pair_id": "conflict_b2d19e8114db4901bba9fa94", "claim_ids": ["claim_72c5f35f3ec01a4cbc0a8b65", "claim_7c70883b759cf0551517d247"], "query_ids": ["q_62"], "claims": [{"claim_id": "claim_72c5f35f3ec01a4cbc0a8b65", "quote": "the United States imposed a 15% tariff on most imports from Japan, a reduction from the 25% that President Trump initially proposed but an increase from 2024 U.S. tariff rates.", "url": "https://www.congress.gov/crs-product/IN12608", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "United States", "duty_rate": "15%", "announcement_date": "July 2025", "effective_date": "2025", "reported_policy_status": "imposed"}}, {"claim_id": "claim_7c70883b759cf0551517d247", "quote": "Japan ($69 billion in 2024), which was to face a 25% country-specific tariff.", "url": "https://www.congress.gov/crs-product/IN12608", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Japan", "duty_rate": "25%", "effective_date": "2024"}}]}]}

